-- Genuine Root material only after the one protected case completed. No fake positive proof.
BEGIN; SET LOCAL search_path=pg_catalog,public,extensions; SET LOCAL lock_timeout='5s'; SET LOCAL statement_timeout='30s';
SELECT set_config('tus.human_custom_open',$openpermit${"authority_sha256":"86a5d88e7071257ca6e2c3d5564c4ab7d7f58074a3854445edb060ca50eb4deb","capability_sha256":"a65259745010e998aee598a7b85f23ac3e7e2645d4c8628eead2ee2767c33c21","expected_case":{"arc_md5":"cba86d9d434819368b13f164bb4bae70","combat_md5":"280c72283fdab18660c261072ac53e9a","master_md5":"d275d315d44b3e871d2c17fe6b459313","report_md5":"aeffb4eb1f29ba9937baa1b483fe0058","source_md5":"f8ea0abbb5717618b4c4d06aa88c7f13","terminal_md5":"0add41d99ff3baeb14c25535758507ec","protected_md5":"d41adde267a202a8ff4c6c194eb0a09f"},"expected_fixed30":{"singleton":true,"staff_enabled":false,"public_enabled":false,"allowed_auth_ids":["f0856d53-83a6-4de0-bc0c-12c87916e665","b4952ed5-5ce0-49c0-9f2b-8fd5dcd89b4b"],"public_policy_id":"2fe96b8c-37f6-4910-a38e-2ddd47f5a12a","public_call_limit":null,"public_staff_enabled":true,"qualification_sha256":null,"public_release_sha256":"5ab4234b32294cc26472855447e6230f62c5e07308768816ae0c2ea304d94366","public_staff_draft_id":"770f2d68-2775-546d-98a6-7297335e4edf","public_cost_budget_usd":null,"scheduler_staff_enabled":false,"scheduler_public_enabled":false,"public_staff_draft_version":2,"public_staff_source_sha256":"24d6b0730cf1fcc78a821c49955addcef8dd320ce93316744f306693247cf726","public_count_upper_cost_usd":null,"public_qualification_sha256":"8fbc6510cd610149a232f90f3d8c8b97aa8a28a92a632c6b1702af58b1185083","public_staff_release_sha256":"5ab4234b32294cc26472855447e6230f62c5e07308768816ae0c2ea304d94366","scheduler_public_evidence_ref":null,"public_staff_test_manifest_ref":"management/candidati/NARRATORE-UNIFICATO_2026-09-02/candidato/exam_human_master/HUMAN_CUSTOM_ORDINARY_MANIFEST.json","public_count_qualification_sha256":null,"public_staff_qualification_sha256":"f5a4e399571d9de883d595f5836cb9c4e21163b9f59412db598885e5ebc7678c","scheduler_staff_test_manifest_ref":"management/candidati/NARRATORE-UNIFICATO_2026-09-02/candidato/mission_factory_unified/C869_MANIFEST.json","scheduler_staff_qualification_sha256":"cc705e3481e2ced87ffe3df9ac77f4e1f730d2a7b5f08cfe761f4a5b0af494f0","scheduler_public_qualification_sha256":null},"expected_release":{"db_sha256":"108c99582f3cd3a7516de4a1b026c47a3a503975f2cd3d940c98a107d2ceeb3c","created_at":"2026-10-16T21:22:11.748748+00:00","edge_sha256":"4a1c4a611109e7f01f3806327ee7c83842a2f6380436aba3cd5e9529b5f5691b","qualified_at":"2026-10-16T21:22:11.748748+00:00","client_sha256":"265449eae162babf04f3415d8eb11a7bc3288ba3ef225940f423be7b4932d8a6","public_enabled":false,"release_sha256":"a65259745010e998aee598a7b85f23ac3e7e2645d4c8628eead2ee2767c33c21","contract_version":"mission-public-admission/1","staff_evidence_ref":"AUTHORIZED_TEST_MANIFEST:management/candidati/NARRATORE-UNIFICATO_2026-09-02/candidato/exam_human_master/HUMAN_CUSTOM_ORDINARY_MANIFEST.json","configuration_sha256":"fc85675e94f9a34eb53663b9c5eeb9d2019675e6f7ba61dd0f1d0253acc31c4d","independent_review_ref":"management/candidati/NARRATORE-UNIFICATO_2026-09-02/candidato/exam_human_master/HUMAN_CUSTOM_ORDINARY_REVIEW.json"},"expires_at":"2026-10-16T21:35:52.428447+00:00","operation":"open_exact_human_custom_after_staff_pass","positive_payload":{"schema_version":"human-custom-positive-staff/1","capability_sha256":"a65259745010e998aee598a7b85f23ac3e7e2645d4c8628eead2ee2767c33c21","session_id":"9845891c-2e02-5ba6-8b45-68ff9f2fe268","terminal_receipt_id":"535535b1-340e-4472-a4a0-9d1914fc739f","encounter_id":"9f5ad733-ea91-434f-8ffd-1a3c818e1e70","report_id":"5aeb80a8-2069-4488-bcd2-db245cd9021b","protected_before_md5":"d41adde267a202a8ff4c6c194eb0a09f","protected_after_md5":"d41adde267a202a8ff4c6c194eb0a09f","provider_calls":0},"positive_ref":"management/candidati/NARRATORE-UNIFICATO_2026-09-02/candidato/exam_human_master/HUMAN_CUSTOM_ORDINARY_QA.json","request_key":"bf6f7b89-27cb-479a-a3aa-07c8d7338d86","review_ref":"management/candidati/NARRATORE-UNIFICATO_2026-09-02/candidato/exam_human_master/HUMAN_CUSTOM_ORDINARY_REVIEW.json","review_sha256":"d1ad140817c3ccac8068cc43d86ae8fc6388074a684605e741abaf4ef70c6001"}$openpermit$,true);
DO $custom_open$
DECLARE v_ev jsonb:=nullif(current_setting('tus.human_custom_open',true),'')::jsonb;
 g mission_factory_owner.quest_fixed30_admission;ad mission_public_owner.release_admissions_v1;
 src mission_factory_owner.quest_run_sources;ar mission_factory_owner.quest_arcs;tr mission_factory_owner.quest_terminal_receipts;
 open_ad mission_public_owner.release_admissions_v1;open_positive mission_public_owner.public_qualification_attestations_v1;open_g mission_factory_owner.quest_fixed30_admission;open_force_staff boolean;open_default_draft uuid;open_observation jsonb;
 pos record;observation jsonb;csha text;keysha text;v_case jsonb;v_md5 text;v_gpost jsonb;v_rpost jsonb;
BEGIN
 IF current_user IS DISTINCT FROM 'postgres'::name OR auth.uid() IS NOT NULL OR v_ev IS NULL OR jsonb_typeof(v_ev) IS DISTINCT FROM 'object'
 OR v_ev->>'expires_at' IS NULL OR (v_ev->>'expires_at')::timestamptz<=clock_timestamp() OR (v_ev->>'expires_at')::timestamptz>clock_timestamp()+interval '10 minutes'
 OR coalesce(v_ev->>'authority_sha256','')!~'^[0-9a-f]{64}$' OR coalesce(v_ev->>'review_sha256','')!~'^[0-9a-f]{64}$' OR nullif(btrim(v_ev->>'review_ref'),'') IS NULL
 THEN RAISE EXCEPTION 'HUMAN_CUSTOM_OPEN_FINITE_ROOT_AUTHORITY_REQUIRED';END IF;
 IF (SELECT array_agg(k ORDER BY k) FROM jsonb_object_keys(v_ev) k) IS DISTINCT FROM ARRAY['authority_sha256','capability_sha256','expected_case','expected_fixed30','expected_release','expires_at','operation','positive_payload','positive_ref','request_key','review_ref','review_sha256']::text[]
 OR v_ev->>'operation' IS DISTINCT FROM 'open_exact_human_custom_after_staff_pass'
 OR coalesce(v_ev->>'capability_sha256','')!~'^[0-9a-f]{64}$' OR jsonb_typeof(v_ev->'expected_case') IS DISTINCT FROM 'object'
 OR jsonb_typeof(v_ev->'expected_fixed30') IS DISTINCT FROM 'object' OR jsonb_typeof(v_ev->'expected_release') IS DISTINCT FROM 'object'
 OR nullif(btrim(v_ev->>'positive_ref'),'') IS NULL OR v_ev->>'request_key' IS NULL
 THEN RAISE EXCEPTION 'HUMAN_CUSTOM_OPEN_CLOSED_ROOT_INPUT';END IF;
 csha:=v_ev->>'capability_sha256';
 SELECT v_ev->'positive_payload' AS payload INTO pos;
 IF mission_factory_owner.keys_exact_v2(pos.payload,ARRAY['schema_version','capability_sha256','session_id','terminal_receipt_id','encounter_id','report_id','protected_before_md5','protected_after_md5','provider_calls']) IS DISTINCT FROM true
 OR pos.payload->>'schema_version' IS DISTINCT FROM 'human-custom-positive-staff/1' OR pos.payload->>'capability_sha256' IS DISTINCT FROM csha
 OR pos.payload->'provider_calls' IS DISTINCT FROM '0'::jsonb OR coalesce(pos.payload->>'protected_before_md5','')!~'^[0-9a-f]{32}$'
 OR pos.payload->>'protected_before_md5' IS DISTINCT FROM pos.payload->>'protected_after_md5'
 THEN RAISE EXCEPTION 'HUMAN_CUSTOM_OPEN_REAL_POSITIVE_PROOF_REQUIRED';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('human-custom-ordinary-release',15102026));
 SELECT * INTO STRICT g FROM mission_factory_owner.quest_fixed30_admission WHERE singleton FOR UPDATE;
 SELECT * INTO STRICT ad FROM mission_public_owner.release_admissions_v1 WHERE release_sha256=csha FOR UPDATE;
 PERFORM 1 FROM public.master_v2_sessions WHERE id=(pos.payload->>'session_id')::uuid FOR UPDATE;
 PERFORM 1 FROM public.combat_v2_sessions WHERE id=(pos.payload->>'encounter_id')::uuid FOR UPDATE;
 PERFORM 1 FROM public.combat_v2_rounds WHERE session_id=(pos.payload->>'encounter_id')::uuid ORDER BY id FOR UPDATE;
 PERFORM 1 FROM public.combat_v2_round_reports WHERE id=(pos.payload->>'report_id')::uuid FOR SHARE;
 SELECT * INTO STRICT src FROM mission_factory_owner.quest_run_sources WHERE session_id=(pos.payload->>'session_id')::uuid FOR SHARE;
 SELECT * INTO STRICT ar FROM mission_factory_owner.quest_arcs WHERE id=src.arc_id FOR SHARE;
 SELECT * INTO STRICT tr FROM mission_factory_owner.quest_terminal_receipts WHERE id=(pos.payload->>'terminal_receipt_id')::uuid FOR SHARE;
 IF to_jsonb(g) IS DISTINCT FROM v_ev->'expected_fixed30' OR to_jsonb(ad) IS DISTINCT FROM v_ev->'expected_release' OR ad.public_enabled IS DISTINCT FROM false
 OR g.public_enabled IS DISTINCT FROM false OR g.staff_enabled IS DISTINCT FROM false OR g.scheduler_public_enabled IS DISTINCT FROM false OR g.scheduler_staff_enabled IS DISTINCT FROM false
 OR g.public_staff_draft_id IS DISTINCT FROM ar.draft_id OR g.public_staff_source_sha256 IS DISTINCT FROM ar.source_sha256
 OR g.public_staff_release_sha256 IS DISTINCT FROM '5ab4234b32294cc26472855447e6230f62c5e07308768816ae0c2ea304d94366'
 THEN RAISE EXCEPTION 'HUMAN_CUSTOM_OPEN_FULL_CONFIG_DRIFT';END IF;
 observation:=mission_factory_owner.human_ordinary_release_identity_v1('5ab4234b32294cc26472855447e6230f62c5e07308768816ae0c2ea304d94366',true);
 IF observation->>'observed_revision_sha256' IS DISTINCT FROM csha OR mission_factory_owner.human_release_observation_valid_v1(observation,'5ab4234b32294cc26472855447e6230f62c5e07308768816ae0c2ea304d94366',true) IS DISTINCT FROM true THEN RAISE EXCEPTION 'HUMAN_CUSTOM_OPEN_OBSERVED_VERSION_DRIFT';END IF;
 IF (src.state='terminal' AND src.availability_scope='public' AND src.execution_context='staff_simulation' AND src.public_release_sha256='5ab4234b32294cc26472855447e6230f62c5e07308768816ae0c2ea304d94366' AND src.location_id='0b85f354-9cdb-47e1-baf9-3d266bb7e06b'::uuid
 AND src.terminal_receipt_id=tr.id AND tr.session_id=src.session_id AND tr.source_sha256=src.source_sha256 AND tr.outcome='success' AND tr.publication_id IS NOT NULL AND ar.state='completed' AND cardinality(ar.execution_auth_ids)=2 AND cardinality(ar.member_character_ids)=2
 AND EXISTS(SELECT 1 FROM mission_public_owner.public_qualification_attestations_v1 sp WHERE sp.release_sha256=mission_factory_owner.sha(jsonb_build_object('schema_version','human-custom-source-key/1','publication_request',ar.publication_request)) AND sp.created_by='postgres'::name AND sp.payload->>'schema_version'='human-custom-source/1' AND (sp.payload->>'capability_sha256'=csha OR (sp.payload->>'capability_sha256' IS DISTINCT FROM csha AND (mission_factory_owner.human_staff_context_records_v1(observation,csha,ar.id,'continuity_historical',g) OR mission_factory_owner.human_staff_lease_valid_v1(observation,ar.id,false)))) AND sp.payload->>'source_sha256'=ar.source_sha256 AND sp.payload->>'arc_id'=ar.id::text AND sp.payload_sha256=mission_factory_owner.sha(sp.payload))
 AND EXISTS(SELECT 1 FROM public.master_v2_sessions mm WHERE mm.id=src.session_id AND mm.owner_kind='human' AND mm.stato='chiusa' AND mm.closed_at IS NOT NULL)
 AND EXISTS(SELECT 1 FROM public.mission_run_outbox ox WHERE ox.event_id=tr.close_event_id AND ox.master_session_id=src.session_id AND ox.state='published' AND ox.publication_id=tr.publication_id)
 AND EXISTS(SELECT 1 FROM public.combat_v2_sessions cs JOIN public.combat_v2_rounds cr ON cr.session_id=cs.id JOIN public.combat_v2_round_reports rp ON rp.round_id=cr.id JOIN mission_generic_owner.regia_human_windows_v1 hw ON hw.master_session_id=src.session_id AND hw.encounter_id=cs.id AND hw.source_report_id=rp.id AND hw.source_report_sha256=rp.mechanics_sha256 AND hw.message_id=rp.message_id WHERE cs.id=(pos.payload->>'encounter_id')::uuid AND cs.master_session_id=src.session_id AND cs.state='chiuso' AND cs.closed_at IS NOT NULL AND rp.id=(pos.payload->>'report_id')::uuid AND rp.narration_state='pubblicata' AND rp.values_written=false AND hw.state='published' AND (SELECT count(*) FROM public.combat_v2_narratives nn WHERE nn.report_id=rp.id AND nn.kind='fato_umano')=1)
 AND EXISTS(SELECT 1 FROM public.combat_v2_provider_instances_v1 pi JOIN public.nb_mechanical_versions cv ON cv.id=pi.mechanical_version_ref WHERE pi.session_id=(pos.payload->>'encounter_id')::uuid AND pi.provider='ninja_book' AND cv.profile_kind='npc_custom' AND cv.review_state='approved' AND pi.source_sha256=cv.content_sha256 AND pi.snapshot_sha256=public.combat_v2_sha256(pi.snapshot))
 AND EXISTS(SELECT 1 FROM mission_factory_owner.quest_reward_decisions_v2 rd WHERE rd.arc_id=ar.id AND rd.terminal_receipt_id=tr.id AND rd.effect_mode='simulation' AND rd.receipt->>'state'='simulated' AND rd.receipt->>'computed_xp_per_recipient'='30' AND rd.receipt->>'effective_xp_per_recipient'='0' AND rd.receipt->>'ryo_per_recipient'='0' AND rd.receipt->'items'='[]'::jsonb)
 AND NOT EXISTS(SELECT 1 FROM public.combat_v2_resource_ledger rl WHERE rl.session_id=(pos.payload->>'encounter_id')::uuid AND rl.is_simulated IS DISTINCT FROM true)
 AND NOT EXISTS(SELECT 1 FROM mission_narrative_internal.dispatch_receipts zpd WHERE zpd.master_session_id=src.session_id)
 AND NOT EXISTS(SELECT 1 FROM mission_narrative_internal.dispatch_attempts zpa JOIN mission_narrative_internal.dispatch_receipts zpr ON zpr.id=zpa.receipt_id WHERE zpr.master_session_id=src.session_id)
 AND NOT EXISTS(SELECT 1 FROM mission_generic_owner.work_items zpw WHERE zpw.master_session_id=src.session_id)) IS DISTINCT FROM true THEN RAISE EXCEPTION 'HUMAN_CUSTOM_OPEN_ACTUAL_STAFF_PATH_NOT_PROVEN';END IF;
 SELECT ((WITH targets(label,character_id) AS (VALUES ('pg_tamako','f335b077-34a1-41c3-94aa-58ec674b649b'::uuid),('master_riuji','6bceee99-974f-426b-8d92-38b43b4a4267'::uuid)), resources AS (select t.label,c.rank,c.vita,c.vita_max,c.chakra,c.chakra_max,c.exp,c.xp_lifetime,c.money,c.pool_concesso,c.unspent_points,md5(jsonb_build_array(c.taijutsu,c.ninjutsu,c.genjutsu,c.forza,c.velocita,c.mente,c.resistenza,c.fuuinjutsu,c.kekkei_genkai,c.lealta,c.via,c.fama,c.slot_extra)::text) stats_md5,(select count(*) from public.character_inventory x where x.character_id=c.id) inventory_count,(select md5(coalesce(jsonb_agg(jsonb_build_array(x.id,x.item_id,x.quantity,x.created_at) order by x.id),'[]'::jsonb)::text) from public.character_inventory x where x.character_id=c.id) inventory_md5,(select count(*) from public.lesson_progress x where x.user_id=c.user_id) lesson_count,(select md5(coalesce(jsonb_agg(jsonb_build_array(x.id,x.lesson_id,x.completed_at) order by x.id),'[]'::jsonb)::text) from public.lesson_progress x where x.user_id=c.user_id) lesson_md5,(select count(*) from public.character_jutsu x where x.user_id=c.user_id) jutsu_count,(select md5(coalesce(jsonb_agg(jsonb_build_array(x.id,x.jutsu_id,x.source,x.learned_at) order by x.id),'[]'::jsonb)::text) from public.character_jutsu x where x.user_id=c.user_id) jutsu_md5,(select count(*) from public.character_abilities x where x.character_id=c.id) ability_count,(select md5(coalesce(jsonb_agg(jsonb_build_array(x.id,x.technique_id,x.state,x.sessions_done,x.started_at,x.activated_at) order by x.id),'[]'::jsonb)::text) from public.character_abilities x where x.character_id=c.id) ability_md5,(select count(*) from public.character_perks x where x.character_id=c.id) perk_count,(select md5(coalesce(jsonb_agg(jsonb_build_array(x.id,x.tipo,x.dettaglio,x.costo,x.grado_tecnica,x.created_at) order by x.id),'[]'::jsonb)::text) from public.character_perks x where x.character_id=c.id) perk_md5,(select count(*) from public.esame_prove x where x.candidate_user=c.user_id and x.stato='aperta') legacy_exam_open,(select count(*) from exam_regia_private.bindings x where x.owner_user=c.user_id and x.state<>'closed') legacy_binding_open,md5(jsonb_build_array(c.clan,c.element,c.element2,c.cercoterio,c.sigillo)::text) identity_build_md5 from targets t join public.characters c on c.id=t.character_id order by t.label) select jsonb_build_object('at',clock_timestamp(),'protected_md5',md5(jsonb_agg(to_jsonb(r) order by label)::text),'rows',count(*),'fields_per_pg',(select count(*) from jsonb_object_keys((select to_jsonb(x)-'label' from resources x limit 1)))) from resources r))->>'protected_md5' INTO v_md5;
 IF v_md5 IS DISTINCT FROM pos.payload->>'protected_after_md5' THEN RAISE EXCEPTION 'HUMAN_CUSTOM_OPEN_PROTECTED_RESOURCES_DRIFT';END IF;
 v_case:=jsonb_build_object('source_md5',md5(to_jsonb(src)::text),'arc_md5',md5(to_jsonb(ar)::text),'terminal_md5',md5(to_jsonb(tr)::text),'master_md5',(SELECT md5(to_jsonb(cm)::text) FROM public.master_v2_sessions cm WHERE cm.id=src.session_id),'combat_md5',(SELECT md5(to_jsonb(cc)::text) FROM public.combat_v2_sessions cc WHERE cc.id=(pos.payload->>'encounter_id')::uuid),'report_md5',(SELECT md5(to_jsonb(cr)::text) FROM public.combat_v2_round_reports cr WHERE cr.id=(pos.payload->>'report_id')::uuid),'protected_md5',v_md5);
 IF v_case IS DISTINCT FROM v_ev->'expected_case' THEN RAISE EXCEPTION 'HUMAN_CUSTOM_OPEN_EXACT_COMPLETED_CASE_DRIFT';END IF;
 keysha:=mission_factory_owner.sha(jsonb_build_object('schema_version','human-custom-positive-key/1','capability_sha256',csha));
 INSERT INTO mission_public_owner.release_admissions_v1(release_sha256,contract_version,db_sha256,edge_sha256,client_sha256,configuration_sha256,independent_review_ref,staff_evidence_ref,qualified_at,public_enabled)
 VALUES(keysha,ad.contract_version,ad.db_sha256,ad.edge_sha256,ad.client_sha256,ad.configuration_sha256,ad.independent_review_ref,'SOURCE_RECORD_ONLY:HUMAN_CUSTOM_POSITIVE_PROOF_PARENT',ad.qualified_at,false) ON CONFLICT(release_sha256) DO NOTHING;
 IF NOT EXISTS(SELECT 1 FROM mission_public_owner.release_admissions_v1 pr WHERE pr.release_sha256=keysha AND pr.public_enabled=false AND pr.contract_version=ad.contract_version AND pr.db_sha256=ad.db_sha256 AND pr.edge_sha256=ad.edge_sha256 AND pr.client_sha256=ad.client_sha256 AND pr.configuration_sha256=ad.configuration_sha256 AND pr.independent_review_ref=ad.independent_review_ref AND pr.staff_evidence_ref='SOURCE_RECORD_ONLY:HUMAN_CUSTOM_POSITIVE_PROOF_PARENT' AND pr.qualified_at=ad.qualified_at) THEN RAISE EXCEPTION 'HUMAN_CUSTOM_OPEN_PROOF_PARENT_CONFLICT';END IF;
 INSERT INTO mission_public_owner.public_qualification_attestations_v1(release_sha256,request_key,payload,payload_sha256,positive_staff_evidence_ref,authorized_test_manifest_ref,created_by)
 VALUES(keysha,(v_ev->>'request_key')::uuid,pos.payload,mission_factory_owner.sha(pos.payload),v_ev->>'positive_ref',g.public_staff_test_manifest_ref,'postgres') ON CONFLICT(release_sha256) DO NOTHING;
 IF NOT EXISTS(SELECT 1 FROM mission_public_owner.public_qualification_attestations_v1 pp WHERE pp.release_sha256=keysha AND pp.request_key=(v_ev->>'request_key')::uuid AND pp.created_by='postgres'::name AND pp.payload IS NOT DISTINCT FROM pos.payload AND pp.payload_sha256=mission_factory_owner.sha(pos.payload) AND pp.positive_staff_evidence_ref=v_ev->>'positive_ref' AND pp.authorized_test_manifest_ref=g.public_staff_test_manifest_ref) THEN RAISE EXCEPTION 'HUMAN_CUSTOM_OPEN_POSITIVE_PROOF_CONFLICT';END IF;
 UPDATE mission_public_owner.release_admissions_v1 SET public_enabled=true WHERE release_sha256=csha;
 UPDATE mission_factory_owner.quest_fixed30_admission SET public_staff_enabled=false WHERE singleton;
 v_rpost:=jsonb_set(to_jsonb(ad),'{public_enabled}','true');v_gpost:=jsonb_set(to_jsonb(g),'{public_staff_enabled}','false');
 IF (SELECT to_jsonb(cr) FROM mission_public_owner.release_admissions_v1 cr WHERE cr.release_sha256=csha) IS DISTINCT FROM v_rpost OR (SELECT to_jsonb(cg) FROM mission_factory_owner.quest_fixed30_admission cg WHERE singleton) IS DISTINCT FROM v_gpost
 THEN RAISE EXCEPTION 'HUMAN_CUSTOM_OPEN_POST_CONFIG_DRIFT';END IF;

 -- Re-evaluate the REAL public capability branch after both normal OPEN updates. No Auth impersonation/helper gameplay call.
 open_observation:=mission_factory_owner.human_ordinary_release_identity_v1('5ab4234b32294cc26472855447e6230f62c5e07308768816ae0c2ea304d94366',true);
 SELECT * INTO STRICT open_ad FROM mission_public_owner.release_admissions_v1 WHERE release_sha256=csha;
 SELECT * INTO STRICT open_positive FROM mission_public_owner.public_qualification_attestations_v1 WHERE release_sha256=keysha;
 SELECT * INTO STRICT open_g FROM mission_factory_owner.quest_fixed30_admission WHERE singleton;
 open_default_draft:=nullif(open_observation#>>'{observed_canonical_tuple,config,policy,custom_native_draft_id}','')::uuid;
 open_force_staff:=(open_g.public_staff_enabled AND open_default_draft=open_g.public_staff_draft_id) OR EXISTS(SELECT 1 FROM mission_factory_owner.quest_arcs open_default_arc WHERE open_default_arc.draft_id=open_default_draft AND open_default_arc.availability_scope='public' AND open_default_arc.execution_context='staff_simulation' AND open_default_arc.source_document->>'content_kind'='quest_human');
 IF mission_factory_owner.human_release_observation_valid_v1(open_observation,'5ab4234b32294cc26472855447e6230f62c5e07308768816ae0c2ea304d94366',true) IS DISTINCT FROM true
 OR open_observation->>'observed_revision_sha256' IS DISTINCT FROM csha
 OR (NOT coalesce(open_force_staff,false) AND open_ad.public_enabled AND open_positive.created_by='postgres'::name AND open_positive.payload_sha256=mission_factory_owner.sha(open_positive.payload)
 AND mission_factory_owner.keys_exact_v2(open_positive.payload,ARRAY['schema_version','capability_sha256','session_id','terminal_receipt_id','encounter_id','report_id','protected_before_md5','protected_after_md5','provider_calls'])
 AND open_positive.payload->>'schema_version'='human-custom-positive-staff/1' AND open_positive.payload->>'capability_sha256'=csha AND open_positive.payload->'provider_calls'='0'::jsonb
 AND coalesce(open_positive.payload->>'protected_before_md5','')~'^[0-9a-f]{32}$' AND open_positive.payload->>'protected_before_md5'=open_positive.payload->>'protected_after_md5') IS DISTINCT FROM true
 OR (src.state='terminal' AND src.availability_scope='public' AND src.execution_context='staff_simulation' AND src.public_release_sha256='5ab4234b32294cc26472855447e6230f62c5e07308768816ae0c2ea304d94366' AND src.location_id='0b85f354-9cdb-47e1-baf9-3d266bb7e06b'::uuid
 AND src.terminal_receipt_id=tr.id AND tr.session_id=src.session_id AND tr.source_sha256=src.source_sha256 AND tr.outcome='success' AND tr.publication_id IS NOT NULL AND ar.state='completed' AND cardinality(ar.execution_auth_ids)=2 AND cardinality(ar.member_character_ids)=2
 AND EXISTS(SELECT 1 FROM mission_public_owner.public_qualification_attestations_v1 sp WHERE sp.release_sha256=mission_factory_owner.sha(jsonb_build_object('schema_version','human-custom-source-key/1','publication_request',ar.publication_request)) AND sp.created_by='postgres'::name AND sp.payload->>'schema_version'='human-custom-source/1' AND (sp.payload->>'capability_sha256'=csha OR (sp.payload->>'capability_sha256' IS DISTINCT FROM csha AND (mission_factory_owner.human_staff_context_records_v1(open_observation,csha,ar.id,'continuity_historical',g) OR mission_factory_owner.human_staff_lease_valid_v1(open_observation,ar.id,false)))) AND sp.payload->>'source_sha256'=ar.source_sha256 AND sp.payload->>'arc_id'=ar.id::text AND sp.payload_sha256=mission_factory_owner.sha(sp.payload))
 AND EXISTS(SELECT 1 FROM public.master_v2_sessions mm WHERE mm.id=src.session_id AND mm.owner_kind='human' AND mm.stato='chiusa' AND mm.closed_at IS NOT NULL)
 AND EXISTS(SELECT 1 FROM public.mission_run_outbox ox WHERE ox.event_id=tr.close_event_id AND ox.master_session_id=src.session_id AND ox.state='published' AND ox.publication_id=tr.publication_id)
 AND EXISTS(SELECT 1 FROM public.combat_v2_sessions cs JOIN public.combat_v2_rounds cr ON cr.session_id=cs.id JOIN public.combat_v2_round_reports rp ON rp.round_id=cr.id JOIN mission_generic_owner.regia_human_windows_v1 hw ON hw.master_session_id=src.session_id AND hw.encounter_id=cs.id AND hw.source_report_id=rp.id AND hw.source_report_sha256=rp.mechanics_sha256 AND hw.message_id=rp.message_id WHERE cs.id=(open_positive.payload->>'encounter_id')::uuid AND cs.master_session_id=src.session_id AND cs.state='chiuso' AND cs.closed_at IS NOT NULL AND rp.id=(open_positive.payload->>'report_id')::uuid AND rp.narration_state='pubblicata' AND rp.values_written=false AND hw.state='published' AND (SELECT count(*) FROM public.combat_v2_narratives nn WHERE nn.report_id=rp.id AND nn.kind='fato_umano')=1)
 AND EXISTS(SELECT 1 FROM public.combat_v2_provider_instances_v1 pi JOIN public.nb_mechanical_versions cv ON cv.id=pi.mechanical_version_ref WHERE pi.session_id=(open_positive.payload->>'encounter_id')::uuid AND pi.provider='ninja_book' AND cv.profile_kind='npc_custom' AND cv.review_state='approved' AND pi.source_sha256=cv.content_sha256 AND pi.snapshot_sha256=public.combat_v2_sha256(pi.snapshot))
 AND EXISTS(SELECT 1 FROM mission_factory_owner.quest_reward_decisions_v2 rd WHERE rd.arc_id=ar.id AND rd.terminal_receipt_id=tr.id AND rd.effect_mode='simulation' AND rd.receipt->>'state'='simulated' AND rd.receipt->>'computed_xp_per_recipient'='30' AND rd.receipt->>'effective_xp_per_recipient'='0' AND rd.receipt->>'ryo_per_recipient'='0' AND rd.receipt->'items'='[]'::jsonb)
 AND NOT EXISTS(SELECT 1 FROM public.combat_v2_resource_ledger rl WHERE rl.session_id=(open_positive.payload->>'encounter_id')::uuid AND rl.is_simulated IS DISTINCT FROM true)
 AND NOT EXISTS(SELECT 1 FROM mission_narrative_internal.dispatch_receipts zpd WHERE zpd.master_session_id=src.session_id)
 AND NOT EXISTS(SELECT 1 FROM mission_narrative_internal.dispatch_attempts zpa JOIN mission_narrative_internal.dispatch_receipts zpr ON zpr.id=zpa.receipt_id WHERE zpr.master_session_id=src.session_id)
 AND NOT EXISTS(SELECT 1 FROM mission_generic_owner.work_items zpw WHERE zpw.master_session_id=src.session_id)
) IS DISTINCT FROM true
 OR mission_factory_owner.human_staff_lease_valid_v1(open_observation,ar.id,false) IS DISTINCT FROM true
 THEN RAISE EXCEPTION 'HUMAN_CUSTOM_OPEN_REAL_PUBLIC_CAPABILITY_POST';END IF;
END $custom_open$; COMMIT;
